-- Table structure for wp_swca_financial_transactions
DROP TABLE IF EXISTS `wp_swca_financial_transactions`;
CREATE TABLE `wp_swca_financial_transactions` (
  `id` int(11) NOT NULL AUTO_INCREMENT,
  `transaction_date` date NOT NULL,
  `transaction_type` enum('income','expense') NOT NULL,
  `category` varchar(100) DEFAULT NULL,
  `tags` text DEFAULT NULL,
  `description` text NOT NULL,
  `stripe_charge_id` varchar(100) DEFAULT NULL,
  `stripe_payment_intent_id` varchar(100) DEFAULT NULL,
  `gross_amount` decimal(10,2) NOT NULL,
  `stripe_fee` decimal(10,2) DEFAULT 0.00,
  `net_amount` decimal(10,2) NOT NULL,
  `member_id` int(11) DEFAULT NULL,
  `event_name` varchar(255) DEFAULT NULL,
  `payment_method` varchar(50) DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_transaction_date` (`transaction_date`),
  KEY `idx_member_id` (`member_id`),
  KEY `idx_category` (`category`),
  KEY `idx_stripe_charge_id` (`stripe_charge_id`)
) ENGINE=InnoDB DEFAULT CHARSET=latin1 COLLATE=latin1_swedish_ci;


