-- Table structure for wp_swca_payment_history
DROP TABLE IF EXISTS `wp_swca_payment_history`;
CREATE TABLE `wp_swca_payment_history` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `member_id` bigint(20) unsigned NOT NULL,
  `payment_date` date NOT NULL,
  `payment_amount` decimal(10,2) NOT NULL,
  `payment_method` enum('check','cash','credit','stripe','other') NOT NULL DEFAULT 'check',
  `payment_reference` varchar(100) DEFAULT NULL COMMENT 'Check number, transaction ID, etc.',
  `membership_year` varchar(20) NOT NULL COMMENT '2024-2025, 2025-2026, etc.',
  `membership_amount` decimal(10,2) DEFAULT 0.00,
  `donation_amount` decimal(10,2) DEFAULT 0.00,
  `payment_status` enum('pending','cleared','bounced','void') DEFAULT 'cleared',
  `deposit_date` date DEFAULT NULL,
  `bank_account` varchar(50) DEFAULT NULL,
  `notes` text DEFAULT NULL,
  `created_by` bigint(20) unsigned DEFAULT NULL,
  `created_at` timestamp NOT NULL DEFAULT current_timestamp(),
  `updated_at` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp(),
  PRIMARY KEY (`id`),
  KEY `idx_member_id` (`member_id`),
  KEY `idx_payment_date` (`payment_date`),
  KEY `idx_membership_year` (`membership_year`),
  KEY `idx_payment_method` (`payment_method`),
  KEY `idx_payment_reference` (`payment_reference`),
  KEY `idx_payment_status` (`payment_status`)
) ENGINE=InnoDB AUTO_INCREMENT=183 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='Payment history for all member payments';

